// components/Navbar.tsx
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

const NAV_HEIGHT = 80;

const links = [
  { href: "#servicios", label: "Servicios" },
  { href: "#proyectos", label: "Proyectos" },
  { href: "#contacto", label: "Contacto" },
];

export function Navbar() {
  const [isPastHero, setIsPastHero] = useState(false);

  useEffect(() => {
    const hero = document.querySelector<HTMLElement>("[data-hero]");
    if (!hero) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsPastHero(entry.boundingClientRect.bottom <= NAV_HEIGHT);
      },
      {
        threshold: 0,
        rootMargin: `-${NAV_HEIGHT}px 0px 0px`,
      },
    );

    observer.observe(hero);

    return () => observer.disconnect();
  }, []);

  return (
    <header
      data-past-hero={isPastHero}
      className="fixed inset-x-0 top-0 z-50 h-20 text-current"
    >
      {/* El cambio visual se anima con opacity, no repintando fondo y sombra. */}
      <div
        aria-hidden="true"
        className={[
          "pointer-events-none absolute inset-0 -z-10",
          "bg-white/95 shadow-[0_12px_40px_rgba(15,23,42,0.08)]",
          "opacity-0 transition-opacity duration-200 ease-out",
          "motion-reduce:transition-none",
          isPastHero ? "opacity-100" : "",
        ].join(" ")}
      />

      <nav
        aria-label="Navegación principal"
        className="mx-auto flex h-full max-w-7xl items-center justify-between px-5 md:px-8"
      >
        <Link
          href="/"
          aria-label="Ir al inicio"
          className="inline-flex min-h-11 items-center text-lg font-semibold tracking-[-0.03em] outline-none focus-visible:ring-2 focus-visible:ring-current focus-visible:ring-offset-4"
        >
          Estudio
        </Link>

        <ul className="flex items-center gap-1 md:gap-3">
          {links.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                className={[
                  "inline-flex min-h-11 items-center rounded-full px-3",
                  "text-sm font-medium transition-opacity duration-150",
                  "hover:opacity-60",
                  "outline-none focus-visible:ring-2 focus-visible:ring-current",
                  "motion-reduce:transition-none",
                ].join(" ")}
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>
      </nav>
    </header>
  );
}
```

Marca el hero para que el navbar pueda observar su límite:

```tsx
<section data-hero className="min-h-svh">
  {/* Hero */}
</section>

<Navbar />
```

Usa `IntersectionObserver`, así que no agrega un listener de `scroll` ni provoca renders en cada frame. El fondo y la sombra aparecen cuando el borde inferior del hero pasa por debajo de los 80 px del navbar.
